import type { AgentConversation, AgentTokenUsage } from '../../../../data/data_types'
import type { ActionRunHistoryEntry, CommitReference } from '../../../../data/electron_action_bridge'
import {
    conversationFileChangeUsage,
    sumAgentTokenUsage,
    type AgentFileChangeUsage,
} from '../../../../services/agents/agent_usage'

export interface LineUsage {
    commits: CommitReference[]
    deletions: number
    filesChanged: number
    insertions: number
}

interface ActionUsageValues {
    changes: AgentFileChangeUsage
    lines: LineUsage
    tokens: AgentTokenUsage
}

export interface ScopedActionUsage {
    actionCard: ActionUsageValues
    conversation: ActionUsageValues | null
}

const ZERO_FILE_CHANGES: AgentFileChangeUsage = { deletions: 0, insertions: 0 }

function conversationsForActionCard(
    conversations: AgentConversation[],
    liveConversation: AgentConversation | null,
    actionId: string,
    cardInternalId: string,
) {
    const conversationsById = new Map<string, AgentConversation>()
    for (const conversation of conversations) {
        if (conversation.actionId !== actionId || conversation.cardInternalId !== cardInternalId) continue

        conversationsById.set(conversation.id, conversation)
    }
    if (liveConversation?.actionId === actionId && liveConversation.cardInternalId === cardInternalId) {
        conversationsById.set(liveConversation.id, liveConversation)
    }

    return [...conversationsById.values()]
}

function fileChangeUsage(conversations: AgentConversation[]) {
    return conversations.reduce<AgentFileChangeUsage>((total, conversation) => {
        const usage = conversationFileChangeUsage(conversation) ?? ZERO_FILE_CHANGES

        return { deletions: total.deletions + usage.deletions, insertions: total.insertions + usage.insertions }
    }, { deletions: 0, insertions: 0 })
}

function lineUsage(history: ActionRunHistoryEntry[]): LineUsage {
    const commits = history.flatMap((entry) => entry.commits ?? [])

    return commits.reduce((totals, commit) => ({
        commits: totals.commits,
        deletions: totals.deletions + commit.deletions,
        filesChanged: totals.filesChanged + commit.filesChanged,
        insertions: totals.insertions + commit.insertions,
    }), { commits, deletions: 0, filesChanged: 0, insertions: 0 })
}

function usageValues(conversations: AgentConversation[], history: ActionRunHistoryEntry[]): ActionUsageValues {
    return {
        changes: fileChangeUsage(conversations),
        lines: lineUsage(history),
        tokens: sumAgentTokenUsage(conversations.map(({ usage }) => usage)),
    }
}

/** Aggregates every usage metric for conversation and action/card scopes. */
export function scopedActionUsage(
    conversations: AgentConversation[],
    liveConversation: AgentConversation | null,
    displayedConversation: AgentConversation | null,
    history: ActionRunHistoryEntry[],
    actionId: string,
    cardInternalId: string,
): ScopedActionUsage {
    const actionCardConversations = conversationsForActionCard(
        conversations,
        liveConversation,
        actionId,
        cardInternalId,
    )
    const actionCard = usageValues(actionCardConversations, history)
    if (!displayedConversation) return { actionCard, conversation: null }

    const conversationHistory = history.filter((entry) => (
        entry.type === 'agent' && entry.rootConversationId === displayedConversation.id
    ))

    return {
        actionCard,
        conversation: usageValues([displayedConversation], conversationHistory),
    }
}

import { act, cleanup, fireEvent, render, screen } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'
import type { ActionRunEvent } from '../../../../data/action_run_types'
import type { ActionDefinition } from '../../../../data/action_types'
import type { AgentConversation } from '../../../../data/data_types'
import { setActionBridgeOverride, type ElectronActionBridge } from '../../../../data/electron_action_bridge'
import { actionRunRegistry } from '../../../../services/actions/action_run_registry'
import { AppThemeProvider } from '../../../../theme/theme_provider'
import type { ActionConversationStore } from '../../conversation/action_conversation_store'
import type { ActionHistoryStore } from '../state/action_history_store'
import { ActionUsageScopeStore } from './action_usage_scope_store'
import { ActionUsageSummaryOwner } from './action_usage_summary_owner'

const action = { id: 'implement', type: 'agent' } as ActionDefinition
const context = { cardInternalId: 'card-1', file: 'design/F-114.md', kind: 'card' as const }

function conversation(id: string, insertions: number, deletions: number): AgentConversation {
    return {
        actionId: action.id,
        cardInternalId: context.cardInternalId,
        cardPath: context.file,
        completedAt: null,
        entries: [{
            content: 'update: design/F-114.md', deletions, id: `${id}-event`, insertions, kind: 'event',
            providerItemId: `${id}-file`, status: 'completed', timestamp: 'now', type: 'fileChange',
        }],
        hasExplicitTitle: true,
        id,
        path: `design/activity/card.json#conversation=${id}`,
        providerSessions: [],
        startedAt: 'now',
        status: 'running',
        title: id,
        viewed: true,
    }
}

function createConversationStore(selectedConversation: AgentConversation | null) {
    const events = new EventTarget()
    let snapshot = {
        conversations: selectedConversation ? [selectedConversation] : [],
        loading: false,
        selectedConversation,
    }
    const store = {
        conversationOptions: (liveConversation: AgentConversation | null) => {
            const byId = new Map(snapshot.conversations.map((item) => [item.id, item]))
            if (snapshot.selectedConversation) byId.set(snapshot.selectedConversation.id, snapshot.selectedConversation)
            if (liveConversation) byId.set(liveConversation.id, liveConversation)

            return [...byId.values()]
        },
        getSnapshot: () => snapshot,
        subscribe: (listener: () => void) => {
            events.addEventListener('changed', listener)

            return () => events.removeEventListener('changed', listener)
        },
    } as unknown as ActionConversationStore
    const selectConversation = (nextConversation: AgentConversation | null) => {
        snapshot = {
            conversations: nextConversation ? [...snapshot.conversations, nextConversation] : snapshot.conversations,
            loading: false,
            selectedConversation: nextConversation,
        }
        events.dispatchEvent(new Event('changed'))
    }

    return { selectConversation, store }
}

function createHistoryStore() {
    const historySnapshot = { entries: [], error: null }

    return {
        getSnapshot: () => historySnapshot,
        load: vi.fn(async () => undefined),
        subscribe: () => () => undefined,
    } as unknown as ActionHistoryStore
}

function renderOwner(
    conversationStore: ActionConversationStore,
    scopeStore: ActionUsageScopeStore,
    historyStore = createHistoryStore(),
) {
    return render(
        <AppThemeProvider>
            <ActionUsageSummaryOwner
                action={action}
                context={context}
                conversationStore={conversationStore}
                historyStore={historyStore}
                scopeStore={scopeStore}
            />
        </AppThemeProvider>,
    )
}

describe('ActionUsageSummaryOwner', () => {
    afterEach(() => {
        cleanup()
        actionRunRegistry.stop()
        setActionBridgeOverride(null)
    })

    it('updates conversation values after selection changes without changing active scope', () => {
        const firstConversation = conversation('first', 2, 1)
        const secondConversation = conversation('second', 5, 4)
        const { selectConversation, store } = createConversationStore(firstConversation)
        const scopeStore = new ActionUsageScopeStore()
        renderOwner(store, scopeStore)
        fireEvent.click(screen.getByRole('button', { name: 'Changes, Action/card scope' }))

        expect(screen.getByRole('button', { name: 'Changes, Conversation scope' })).toHaveTextContent('changes: +2 / -1')

        act(() => selectConversation(secondConversation))

        expect(scopeStore.getSnapshot()).toBe('conversation')
        expect(screen.getByRole('button', { name: 'Changes, Conversation scope' })).toHaveTextContent('changes: +5 / -4')
    })

    it('includes live updates in action/card totals once and uses live conversation when selected', () => {
        let listener: ((event: ActionRunEvent) => void) | null = null
        setActionBridgeOverride({
            onActionRun: vi.fn((nextListener) => {
                listener = nextListener

                return vi.fn()
            }),
        } as unknown as ElectronActionBridge)
        actionRunRegistry.start()
        const selectedConversation = conversation('selected', 2, 1)
        const { store } = createConversationStore(selectedConversation)
        const scopeStore = new ActionUsageScopeStore()
        renderOwner(store, scopeStore)
        if (!listener) throw new Error('Missing run listener')
        const emit = listener as (event: ActionRunEvent) => void
        const run = {
            actionId: action.id, context, phase: 'main' as const, rootActionId: action.id,
            runId: 'run-1', status: 'running' as const,
        }

        act(() => {
            emit({ ...run, type: 'run' })
            emit({
                ...run,
                type: 'update',
                update: { conversation: conversation('live', 7, 4), kind: 'agentStarted' },
            })
        })

        expect(screen.getByRole('button', { name: 'Changes, Action/card scope' })).toHaveTextContent('changes: +9 / -5')

        fireEvent.click(screen.getByRole('button', { name: 'Changes, Action/card scope' }))
        expect(screen.getByRole('button', { name: 'Changes, Conversation scope' })).toHaveTextContent('changes: +7 / -4')
    })

    it('forces action/card scope when no conversation is displayed', () => {
        const { store } = createConversationStore(null)
        const scopeStore = new ActionUsageScopeStore()
        scopeStore.toggle(true)

        renderOwner(store, scopeStore)

        expect(scopeStore.getSnapshot()).toBe('actionCard')
        expect(screen.getByRole('button', { name: 'Tokens, Action/card scope' })).toBeInTheDocument()
        fireEvent.click(screen.getByRole('button', { name: 'Tokens, Action/card scope' }))
        expect(scopeStore.getSnapshot()).toBe('actionCard')
    })
})

import { afterEach, describe, expect, it, vi } from 'vitest'
import type { ActionRunEvent } from '../../data/action_run_types'
import type { AgentConversation, AgentConversationEntry } from '../../data/data_types'
import { setActionBridgeOverride, type ElectronActionBridge } from '../../data/electron_action_bridge'
import { ActionRunRegistry, notifyActionCardStateChange } from './action_run_registry'

const context = { file: 'design/F-1.md', kind: 'card' as const }

function bridgeWithEvents(overrides: Partial<ElectronActionBridge> = {}) {
    let listener: ((event: ActionRunEvent) => void) | null = null
    const bridge = {
        onActionRun: vi.fn((nextListener) => {
            listener = nextListener

            return vi.fn()
        }),
        ...overrides,
    } as unknown as ElectronActionBridge
    const emit = (event: ActionRunEvent) => {
        if (!listener) throw new Error('Missing run listener')
        listener(event)
    }

    return { bridge, emit }
}

function runEvent(status: ActionRunEvent['status']): ActionRunEvent {
    return { actionId: 'build', context, runId: 'run-1', phase: 'main', rootActionId: 'build', status, type: 'run' }
}

function getRun(service: ActionRunRegistry, runId = 'run-1') {
    const run = service.getRunStore(runId)?.getSnapshot()
    if (!run) throw new Error('Missing run')

    return run
}

function getActiveRun(service: ActionRunRegistry) {
    return service.getContextActiveSnapshot(context)[0] ?? null
}

function agentConversation(entries: AgentConversationEntry[], overrides: Partial<AgentConversation> = {}): AgentConversation {
    return {
        actionId: 'review',
        cardInternalId: null,
        cardPath: context.file,
        completedAt: null,
        entries,
        hasExplicitTitle: true,
        id: 'conversation-1',
        path: 'log.json',
        providerSessions: [],
        startedAt: 'now',
        status: 'running',
        title: 'Review',
        viewed: true,
        ...overrides,
    }
}

