            codexCacheErrorReported: false,
            conversation: { entries: [] },
            environment: { Path: 'C:\\tools' },
            executable: 'codex.cmd',
            id: 'run-1',
            nextSequence: 1,
            onEvent: vi.fn(),
            secretValues: new Set(),
            stderr: '',
            stderrBuffer: '',
            stderrHandling: Promise.resolve(),
